pageStyle:
.card-body {
    width: 960px;
    margin: auto;
    font-size: 16px;
}

h2 {
    color: #185468 !important;
    font-family: 'Barlow Condensed';
    font-style: normal;
    font-weight: 500;
    font-size: 34px;
    line-height: 1.5em;
    margin-bottom: 45px;
}
.resource {
    clear: both;
    margin: 70px 0;
}

.resource img {
    width: 150px;
    float: left;
    margin: 0 50px 50px 0;
}

.resource .name {
    color: #185468 !important;
    font-family: 'Barlow Condensed';
    font-style: normal;
    font-weight: 500;
    font-size: 28px;
    line-height: 1.5em;
    display: block;
}

.resource .visit {
    display: block;
    color: #fff !important;
    position: absolute;
    left: 215px;
    padding: 3px 5px;
    width: auto;
    background: #185468;
    border-radius: 5px;
    font-size: 0.8em;
    margin-top: 5px;
}
